routes = {}

def route(method, path):
    def register(func):
        routes[(method, path)] = func      # remember the handler, return it unchanged
        return func
    return register

@route("GET", "/health")
def health():
    return 200, {"status": "ok"}

@route("POST", "/echo")
def echo(body):
    return 201, body

def handle(method, path, body=None):
    # Find the handler for (method, path) and return its (status, body).
    # Unknown path: (404, {"detail": "Not Found"}).
    # Known path, other method: (405, {"detail": "Method Not Allowed"}).
    # Pass body to the handler only for POST.
    return 501, {"detail": "Not Implemented"}

requests = [("GET", "/health"), ("POST", "/echo", {"msg": "hi"}), ("GET", "/nope"), ("DELETE", "/health")]
for request in requests:
    print(*handle(*request))

