class Database:  # stands in for a Session
    open = True
    def close(self):
        self.open = False

def get_db():
    db = Database()
    try:
        yield db    # the endpoint runs here
    finally:
        db.close()  # after the response

def get_current_user(
    x_api_key: Annotated[
        str | None, Header()] = None,
) -> str:
    if x_api_key != "secret-key":
        raise HTTPException(401, "Bad API key")
    return "ana"

DB = Annotated[Database, Depends(get_db)]
User = Annotated[
