def hash_pw(pw: str, salt=b"") -> str:
    salt = salt or secrets.token_bytes(16)
    d = hashlib.scrypt(pw.encode(), salt=salt,
                       n=2**14, r=8, p=1)
    return salt.hex() + ":" + d.hex()

def check_pw(pw: str, stored: str) -> bool:
    salt = stored.split(":")[0]
    new = hash_pw(pw, bytes.fromhex(salt))
    # constant time, unlike ==
    return hmac.compare_digest(new, stored)

